-- Onboarding 5411 — habilita view "flow" en nav_items y migra el
-- contenido de "Flujo operativo" (antes hardcodeado en FlowView.tsx) a la
-- base, para que sea editable desde /admin.
-- Correr una sola vez en el SQL Editor, después de schema.sql y seed.sql.

alter table public.nav_items drop constraint if exists nav_items_view_check;
alter table public.nav_items add constraint nav_items_view_check
  check (view in ('doc', 'directory', 'checklist', 'flow'));

insert into public.nav_items (id, track_id, label, icon_name, view, layout, content, position)
values (
  $t$wholesale.flujo$t$,
  $t$wholesale$t$,
  $t$Flujo operativo$t$,
  $t$Boxes$t$,
  $t$flow$t$,
  null,
  $jsonseed${"stages":[{"id":"inbound","number":1,"name":"Inbound","short":"Entrada de mercadería al warehouse","phaseVar":"--phase-1","objective":"El cliente avisa que viene mercadería en camino y se prepara el sistema para recibirla correctamente en el warehouse.","responsible":"Equipo BS AS / Operaciones","adminSections":[{"id":"inbound-recepcion-packing-list","title":"1. Recepción del Packing List","html":"<p>La marca envía mail con tracking # + Packing List.</p>\n<p>Con este documento creamos el ASN = significa Advanced Shipping Notice (Aviso de Envío Anticipado)</p>\n<p class=\"font-semibold text-foreground\">Cómo crear un ASN</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/y7goZ96k0eY?autoplay=1&rel=0\" allowfullscreen></iframe></div>\n<p>Y también creamos las CAJAS en Mintsoft. Para que el warehouse sepa cuantas cajas hay en el cargamento.</p>\n<p class=\"font-semibold text-foreground\">Cómo crear una caja</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/doRO4KPgpFo?autoplay=1&rel=0\" allowfullscreen></iframe></div>\n<p>Lo ideal es cargarlo antes de que la mercadería llegue al warehouse para avisarle al sistema y al equipo de Dallas que hay un cargamento próximo a llegar.</p>"},{"id":"inbound-tracker-marca","title":"2. Tracker de la marca","html":"<p>Cada marca tiene su tracker donde ponemos la información de las órdenes y los cargamentos. Una vez generado el ASN debemos anotarlo en la hoja de cargamentos (ASN# +tracking, unidades, caja y ETA).</p>\n<p class=\"font-semibold text-foreground\">Explicación de Tracker</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/4yXZkSGDvDs\" allowfullscreen></iframe></div>"},{"id":"inbound-cargamento","title":"3. Cargamento","html":"<p>Una vez que se recibe la foto de Camilo por el grupo, anotamos el numero de tracking and hacemos el envío de las carton labes (email INBOUND con el nombre de la marca, el número de cargamento y carton labels). Si hay cajas faltantes esperar a que llegue el restante y hablar con la marca si hace falta.</p>\n<p class=\"font-semibold text-foreground\">Como Enviar labels</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/Ox7jbakLZK8\" allowfullscreen></iframe></div>"},{"id":"inbound-validation-tracking","title":"4. Validation Tracking vs ASN - Respuesta a la marca","html":"<p>Se compara las unidades fisicas contra el ASN cargado en sistema. Una vez que finaliza el escaneo, se le envía a la marca el ASN REPORT.</p>\n<p class=\"font-semibold text-foreground\">ASN REPORT</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/HiEPR1qTa6E\" allowfullscreen></iframe></div>"},{"id":"inbound-criticos","title":"Puntos críticos / Validaciones","html":"<ul class=\"list-disc space-y-1.5 pl-5\">\n  <li>Verificar que el ASN se esté generando para el cliente correcto. Siempre filtrar al cliente antes de empezar a cargar.</li>\n  <li>Si un producto no está creado, incluir sus códigos de barras (barcodes) al cargar el ASN.</li>\n  <li>Confirmar que el ASN se encuentre en estado 'AWAITING DELIVERY'; de lo contrario, Samuel no podrá visualizarlo.</li>\n  <li>Al crear las cajas, seleccionar siempre la opción 'RS Transit'.</li>\n</ul>"}],"warehouseSections":[{"id":"inbound-etapa-camilo","title":"Etapa Camilo","html":"<p>1. Camilo recepciona la mercadería y sube las fotos de los cargamentos a Slack al grupo de la marca.</p>\n<p class=\"font-semibold text-foreground\">Video del Warehouse</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/0MqtGJ3c_pY\" allowfullscreen></iframe></div>\n<p class=\"font-semibold text-foreground\">Ejemplo</p>\n<img src=\"/images/flujo/slack-confirma-llegada.png\" alt=\"Ejemplo de confirmación en Slack\" class=\"w-full rounded-xl border border-border\" />\n<p class=\"font-semibold text-foreground\">Audio de Camilo explicando el proceso</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/89CBuovfewA\" allowfullscreen></iframe></div>"},{"id":"inbound-etapa-samuel","title":"Etapa Samuel","html":"<p>2. De acuerdo con las prioridades, Samuel retira las cajas de RS y las lleva a su mesa de trabajo. Luego imprime las etiquetas (labels), organiza las cajas en el orden correspondiente, coloca las etiquetas y comienza el proceso de escaneo.</p>\n<p class=\"font-semibold text-foreground\">Video de Samuel</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/tIrZr1NjnKM\" allowfullscreen></iframe></div>\n<p class=\"font-semibold text-foreground\">Audio de Samuel explicando el proceso</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/xeYgRup3cC4\" allowfullscreen></iframe></div>\n<p>3. Luego de que Samuel termina de escanear la mercadería se agrupa en RS TRANSIT para luego darse locación en su correspondiente Rack/ bin.</p>\n<img src=\"/images/flujo/racks.png\" alt=\"Plano del warehouse — racks\" class=\"w-full rounded-xl border border-border\" />"}]},{"id":"outbound","number":2,"name":"Outbound","short":"Preparación de órdenes de salida","phaseVar":"--phase-4","objective":"Procesar los pedidos que van a salir del warehouse hacia boutiques o majors. Una orden es un pedido de productos a preparar y enviar.","responsible":"Equipo BS AS","adminSections":[{"id":"outbound-recepcion-preparacion","title":"Proceso de recepción y preparación de órdenes","html":"<p>Las órdenes pueden recibirse por distintas vías según la modalidad de trabajo con cada marca.</p>\n<ul class=\"list-disc space-y-1.5 pl-5\">\n  <li>Por correo electrónico.</li>\n  <li>Incluidas dentro de la información enviada al momento de asignar el cargamento.</li>\n  <li>Buscándolas directamente en la plataforma utilizada por la marca.</li>\n  <li>Migradas desde otras plataformas o sistemas integrados (por ejemplo Shipstation) la marca o sistemas externos conectados.</li>\n</ul>\n<p>Una vez recibidas, todas las órdenes deben ingresarse en el Tracker para realizar su seguimiento operativo.</p>\n<p class=\"font-semibold text-foreground\">Ejemplo de recepción de órdenes</p>\n<img src=\"/images/flujo/orden-ejemplo.png\" alt=\"Ejemplo de recepción de órdenes\" class=\"w-full rounded-xl border border-border\" />\n<p>Las órdenes se clasifican según su tipo:</p>\n<ul class=\"list-disc space-y-1.5 pl-5\"><li>Major</li><li>Boutique</li></ul>\n<p>Luego se define la modalidad operativa:</p>\n<ul class=\"list-disc space-y-1.5 pl-5\"><li>Cross Dock: ingreso y despacho inmediato de la mercadería.</li></ul>\n<a href=\"https://app.notion.com/p/Armado-de-Ordenes-3183d576fa0280848566d0081bb6b3cc\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground\">Ver Guía de Cross Dock →</a>\n<ul class=\"list-disc space-y-1.5 pl-5\"><li>Pick &amp; Pack: preparación de pedidos a partir de la mercadería recibida.</li></ul>\n<p><strong>SE CARGAN LAS ORDENES EN MINTSOFT</strong></p>\n<p class=\"font-semibold text-foreground\">Cómo cargar una orden</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/gQlhAAuWubI\" allowfullscreen></iframe></div>"},{"id":"outbound-mandar-armar","title":"Mandar a armar las órdenes","html":"<p>Mandar a armar una orden significa solicitar al warehouse que prepare el pedido recibido por parte de la marca. Hay que cargar la orden en Mintsoft utilizando un template llamado <a href=\"https://docs.google.com/spreadsheets/d/1tTvWVIygN5TXWkee9eNk9JFZB5tOBS3A90u_HqixFUc/edit?gid=896359184#gid=896359184\" target=\"_blank\" rel=\"noopener noreferrer\">SO Mintsoft - 5411 - Subir ordenes</a>. Una vez finalizado el armado, el warehouse enviará una fotografía donde se visualizan las medidas de la caja.</p>\n<p>El proceso de pickeo de las órdenes es exactamente el mismo en ambos casos. La principal diferencia se encuentra en la etapa previa al packing, ya que la preparación de los productos antes de su empaquetado cambia de manera significativa según el tipo de orden.</p>\n<p class=\"font-semibold text-foreground\">Cómo mandar a armar una orden</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/g4vjzUgvAqs\" allowfullscreen></iframe></div>\n<div class=\"rounded-lg border border-yellow-300 bg-yellow-50 p-4\">\n  <p class=\"font-semibold text-yellow-900\">🏷️ Información sobre Fineline (Solo Majors)</p>\n  <p class=\"mt-2 text-yellow-900\">La mayoría de las órdenes <strong>Major</strong> requieren <strong>reetiquetado (Fineline)</strong>. Esto significa que el warehouse debe reemplazar las etiquetas originales de la mercadería por las etiquetas solicitadas por la marca. Estas deben contener el barcode y toda la información requerida por el cliente.</p>\n  <p class=\"mt-2 font-semibold text-yellow-900\">Antes de comenzar el proceso verificar:</p>\n  <ul class=\"list-disc space-y-1 pl-5 text-yellow-900\">\n    <li>Si la orden requiere o no Fineline.</li>\n    <li>Que las etiquetas Fineline ya hayan sido recibidas en el warehouse.</li>\n    <li>Si la orden requiere Hangers.</li>\n  </ul>\n  <p class=\"mt-2 text-yellow-900\"><strong>Importante:</strong> Las etiquetas Fineline pueden ser enviadas por la marca o adquiridas por nuestro equipo. Independientemente de quién las provea, es fundamental anticipar su gestión para que, cuando la mercadería llegue al warehouse, las etiquetas ya se encuentren disponibles.</p>\n  <a href=\"https://drive.google.com/drive/folders/1L72v9unY_jTAdUreHthTsxpTrNmyF3aO?usp=sharing\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-3 inline-flex items-center gap-2 rounded-lg bg-yellow-600 px-4 py-2 text-sm font-semibold text-white\">Ver carpeta de Finelines →</a>\n</div>"},{"id":"outbound-sacar-ordenes","title":"Sacar órdenes","html":"<p>Una vez que una orden se encuentra en estado <strong>PACKED</strong>, significa que el pedido ya fue procesado por el warehouse (pickeo y packeo) y está listo para ser despachado.</p>\n<p class=\"font-semibold text-foreground\">Caja armada - Ejemplo</p>\n<img src=\"/images/flujo/caja-lista.jpeg\" alt=\"Caja armada - ejemplo\" class=\"w-full max-w-md rounded-xl border border-border\" />\n<img src=\"/images/flujo/caja-armada.png\" alt=\"Orden armada - ejemplo\" class=\"w-full max-w-md rounded-xl border border-border\" />\n<p><strong>Órdenes de Boutique con 1 sola caja</strong></p>\n<p>• Si la orden está aprobada para salir, el warehouse (Nairobis) se encarga de generar la etiqueta (label) de UPS.</p>\n<p>• Si la orden no está aprobada para salir, el warehouse (Nairobis) deja la caja preparada e identificada con un sticker rojo, quedando en espera hasta recibir la autorización de despacho.</p>\n<p><strong>Importante:</strong> Al cargar la orden en Mintsoft se debe indicar esta condición (<strong>No aprobada para salir</strong>) en el campo <strong>Packing Notes</strong>.</p>\n<p><strong>Órdenes de Major con 1 sola caja</strong></p>\n<p>• Si la orden está aprobada para salir, el warehouse (Karen / Aida) genera la etiqueta (label) de UPS e imprime toda la documentación cargada en Mintsoft (Packing List, Carton Labels, etc.).</p>\n<p>• Si la orden no está aprobada para salir, el warehouse (Karen / Aida) deja la caja preparada e identificada con un sticker rojo, quedando en espera hasta recibir la autorización de despacho.</p>\n<p><strong>Importante:</strong> Al cargar la orden en Mintsoft se debe indicar esta condición (<strong>No aprobada para salir</strong>) en el campo <strong>Packing Notes</strong>.</p>\n<p><strong>Órdenes Boutique / Major con más de 1 caja</strong></p>\n<p>• Si cuentan con la aprobación para salir, nosotros generamos las etiquetas de UPS junto con la documentación requerida por el Major y enviamos todo al warehouse por correo electrónico con el asunto <strong>'PARA SALIR'</strong>, para que procedan con el despacho.</p>\n<p>Hay órdenes de Majors que requieren una aprobación previa antes de ser despachadas. Este proceso se denomina ruteo y puede realizarse por correo electrónico o a través de un portal específico. En ambos casos, es importante dejar constancia de la solicitud de aprobación en el Tracker.</p>\n<p class=\"font-semibold text-foreground\">Autorización - Ver ejemplo</p>\n<img src=\"/images/flujo/autorizacion.png\" alt=\"Ejemplo de autorización\" class=\"w-full max-w-md rounded-xl border border-border\" />\n<p>Una vez despachada la orden, se debe registrar el Tracking Number en el Tracker y actualizar el estado de la orden para reflejar que el envío ya fue realizado.</p>"},{"id":"outbound-criticos","title":"Puntos críticos / Validaciones","html":"<ul class=\"list-disc space-y-1.5 pl-5\"><li>Actualmente estamos atravesando un proceso de cambios operativos, por lo que esta información podrá actualizarse y modificarse en adelante.</li></ul>"}],"warehouseSections":[{"id":"outbound-armado-orden","title":"Armado de la orden","html":"<p class=\"font-semibold text-foreground\">Ver Video - Armar la orden</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/5ZhUPymlAzc\" allowfullscreen></iframe></div>\n<p>2. El warehouse empieza a armar la caja</p>\n<p class=\"font-semibold text-foreground\">Se empieza a pickear y explicación de fineline (MAJORS)</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/FxI_5ndlJ_k\" allowfullscreen></iframe></div>\n<p class=\"font-semibold text-foreground\">Audio de Karen</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/FyfDM4Bkalc\" allowfullscreen></iframe></div>\n<p class=\"font-semibold text-foreground\">Se empieza a pickear (Boutiques)</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/Nn03MGUuBvY\" allowfullscreen></iframe></div>\n<p class=\"font-semibold text-foreground\">Audio de Nai</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/t3X5y8-8F9Q\" allowfullscreen></iframe></div>\n<p>3. El warehouse termina de armar la caja</p>\n<p class=\"font-semibold text-foreground\">Caja armada - Ejemplo</p>\n<img src=\"/images/flujo/caja-lista.jpeg\" alt=\"Caja armada - ejemplo\" class=\"w-full max-w-md rounded-xl border border-border\" />"},{"id":"outbound-despacho","title":"Despacho","html":"<p>4. Etapa PS: El warehouse (Ana) imprime durante el transcurso del día las etiquetas que armamos manualmente y enviamos por correo electrónico, junto con los packing lists y las carton labels, en caso de ser necesarias. Luego prepara las cajas, dejando todo listo para la llegada del camión de UPS, prevista aproximadamente entre las 16:00 y las 17:00 hs.</p>\n<p>5. Llega el camion de UPS y se lleva las cajas a sus destinos.</p>"}]},{"id":"shipping","number":3,"name":"Returns","short":"Devoluciones","phaseVar":"--phase-8","objective":"Gestionar las devoluciones de nuestros clientes","responsible":"Equipo BS AS","adminSections":[{"id":"returns-general","title":"Returns","html":"<p>En algunos casos, una marca puede solicitar que generes una return label para su cliente. Cuando esto sucede, deberás crearla manualmente en UPS. Para hacerlo, es importante contar con la siguiente información:</p>\n<ul class=\"list-disc space-y-1.5 pl-5\">\n  <li>Datos completos del remitente (quien envía el paquete).</li>\n  <li>Peso de cada caja y medidas de la caja.</li>\n</ul>\n<p>En el campo Reference, siempre se debe ingresar el nombre de la marca + Return (por ejemplo: BrandName - Return). Esto facilita la identificación del envío cuando llega al warehouse.</p>\n<p>También puede pasar que la return label la genere la marca y te avise/ o no que está volviendo mercadería.</p>\n<p>Es importante estar en el grupo de slack #returns-wholesale, ya que allí las chicas van anotando que se proceso o que necesita revision de tu parte.</p>\n<p class=\"font-semibold text-foreground\">Grupo de Slack Returns - Ejemplo</p>\n<img src=\"/images/flujo/grupo-returns.png\" alt=\"Grupo de Slack Returns - ejemplo\" class=\"w-full max-w-md rounded-xl border border-border\" />"}],"warehouseSections":[{"id":"returns-proceso","title":"Proceso de Returns","html":"<p>El warehouse recibe diariamente un gran volumen de returns, tanto de Wholesale como de Ecommerce. Al día siguiente de su recepción, el equipo del warehouse comienza a clasificar los paquetes por marca para dar inicio al proceso de trabajo correspondiente.</p>\n<p class=\"font-semibold text-foreground\">Video del Warehouse</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/pfeDuQki4rA\" allowfullscreen></iframe></div>\n<p>1. Se separan las prendas por marca.</p>\n<p>2. Se Escanea cada prenda en Two Boxes.</p>\n<p class=\"font-semibold text-foreground\">Video de Two Boxes</p>\n<div data-video-embed class=\"aspect-video w-full overflow-hidden rounded-xl border border-border bg-black\"><iframe class=\"h-full w-full\" src=\"https://www.youtube.com/embed/XWj_OOqt8-s\" allowfullscreen></iframe></div>\n<p>3. Realizan el Quality Check de cada prenda.</p>\n<p>4. Cierran el return en el sistema.</p>\n<p>5. Notifican por Slack que el proceso fue completado (con el numero de guia).</p>\n<p>6. Cuando una caja se llena, se le da locación en los racks.</p>"}]}],"faqs":[{"id":"faq-que-es-asn","q":"¿Qué es un ASN?","a":"Advance Shipping Notice — aviso anticipado cargado en Mintsoft con el detalle de la mercadería que va a llegar. Se carga 1 ASN por cada PO."},{"id":"faq-formato-carton","q":"¿Cuál es el formato del código de un Carton?","a":"PRIMERAS DOS LETRAS + últimos 6 dígitos del tracking + número de caja. Ejemplo: MO-468889-1."},{"id":"faq-cuando-enviar-labels","q":"¿Cuándo envío las carton labels al warehouse?","a":"Recién cuando confirman por Slack que llegaron las cajas físicamente."},{"id":"faq-crossdock-vs-pickpack","q":"¿Cuál es la diferencia entre Cross Dock y Pick & Pack?","a":"Cross Dock: la caja entra y sale rápido sin almacenarse. Pick & Pack: el warehouse abre cajas, busca productos y arma nuevas cajas."},{"id":"faq-onbackorder","q":"¿Qué hago si una orden queda en ONBACKORDER?","a":"El stock existe pero no está ubicado correctamente. Es posible que el stock correspondiente a la orden aún no llegó o no se procesó."},{"id":"faq-estados-orden","q":"Cuáles son los estados de una orden?","a":"Tracker: Entered → Packing → Packed → Routed Shipped. / Mintsoft: New → Awaiting picking → Picked → Packed → Despatched o Invoice"},{"id":"faq-cutoff-pickup","q":"¿Cuál es el cutoff de pickup?","a":"4:00 PM. El warehouse cierra a las 5:00 PM. Si no está listo antes del cutoff, queda retenido para el día siguiente."}]}$jsonseed$::jsonb,
  1
)
on conflict (id) do update set content = excluded.content;
